#!/usr/bin/env node
// Writes the two generated files that enumerate the translation catalogs:
//
//   packages/i18n/src/namespaces.ts          — the namespace list the web
//                                              app's lazy loader iterates;
//   packages/ui-native/src/i18n/catalog.generated.ts
//                                            — static imports of every
//                                              (locale, namespace) JSON for
//                                              Metro, which cannot bundle a
//                                              templated import().
//
// Source of truth is the directory packages/i18n/messages/<locale>/*.json.
// Run after adding a namespace: node scripts/i18n/gen-catalog-index.mjs
// CI runs it with --check and fails if the committed files are stale.

import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("../..", import.meta.url));
const MESSAGES = join(ROOT, "packages/i18n/messages");
const CHECK = process.argv.includes("--check");

const locales = readdirSync(MESSAGES)
  .filter((d) => !d.includes("."))
  .sort((a, b) => (a === "en" ? -1 : b === "en" ? 1 : a.localeCompare(b)));
const namespaces = readdirSync(join(MESSAGES, "en"))
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.replace(/\.json$/, ""))
  .sort();

const header =
  "// Generated by scripts/i18n/gen-catalog-index.mjs — do not edit by hand.\n";

const namespacesTs = `${header}
export const I18N_LOCALES = ${JSON.stringify(locales)} as const;
export type I18nLocale = (typeof I18N_LOCALES)[number];

export const I18N_NAMESPACES = ${JSON.stringify(namespaces)} as const;
export type I18nNamespace = (typeof I18N_NAMESPACES)[number];
`;

const ident = (locale, ns) =>
  `${locale}${ns.replace(/[^a-zA-Z0-9]+(.)?/g, (_, c) => (c ? c.toUpperCase() : "")).replace(/^./, (c) => c.toUpperCase())}`;

const imports = [];
const entries = [];
for (const locale of locales) {
  const lines = [];
  for (const ns of namespaces) {
    imports.push(
      `import ${ident(locale, ns)} from "@abonten/i18n/messages/${locale}/${ns}.json";`,
    );
    lines.push(`    ${JSON.stringify(ns)}: ${ident(locale, ns)},`);
  }
  entries.push(`  ${locale}: {\n${lines.join("\n")}\n  },`);
}

const nativeTs = `${header}// Static catalog map for React Native. The web app lazy-imports each
// (locale, namespace) chunk; Metro bundles them all and picks at runtime.

import type { I18nLocale } from "@abonten/i18n/namespaces";
${imports.join("\n")}

export type Messages = Record<string, unknown>;
export type LocaleMessages = Record<string, Messages>;

export const CATALOG: Record<I18nLocale, LocaleMessages> = {
${entries.join("\n")}
};
`;

// The committed files are Biome-formatted (the pre-commit hook would do it
// anyway), so format here too and the --check comparison is exact.
function biomeFormat(path, content) {
  return execFileSync(
    process.execPath,
    [
      join(ROOT, "node_modules/@biomejs/biome/bin/biome"),
      "check",
      "--write",
      `--stdin-file-path=${path}`,
    ],
    { input: content, encoding: "utf8", cwd: ROOT },
  );
}

const outputs = [
  [join(ROOT, "packages/i18n/src/namespaces.ts"), namespacesTs],
  [join(ROOT, "packages/ui-native/src/i18n/catalog.generated.ts"), nativeTs],
].map(([path, content]) => [path, biomeFormat(path, content)]);

let stale = false;
for (const [path, content] of outputs) {
  const current = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (current === content) continue;
  if (CHECK) {
    stale = true;
    console.error(`stale: ${path}`);
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${path}`);
  }
}
if (CHECK && stale) {
  console.error("Run: node scripts/i18n/gen-catalog-index.mjs");
  process.exit(1);
}
if (CHECK)
  console.log(
    `catalog index: ${locales.length} locales × ${namespaces.length} namespaces, up to date.`,
  );
